import os, pty, subprocess, time

def tty_run(args, in_tty, out_tty, feed=None, wait=2.0, label=''):
    masters=[]
    kw={}
    if in_tty:
        mi,si=pty.openpty(); masters.append(mi); kw['stdin']=si
    else:
        kw['stdin']=subprocess.PIPE
    if out_tty:
        mo,so=pty.openpty(); masters.append(mo); kw['stdout']=so
    else:
        kw['stdout']=subprocess.PIPE
    kw['stderr']=subprocess.PIPE
    p=subprocess.Popen(['/workspace/executable']+args, cwd='/tmp/melody-cli', **kw)
    for k in ('stdin','stdout'):
        fd=kw.get(k)
        if isinstance(fd,int) and fd>2:
            try: os.close(fd)
            except: pass
    if not in_tty:
        p.stdin.write(feed or b''); p.stdin.close()
    elif feed is not None:
        os.write(masters[0], feed)
    time.sleep(wait)
    rc=p.poll()
    st = f'exit {rc}' if rc is not None else 'STILL RUNNING'
    out=b''; err=b''
    if rc is None:
        p.kill(); p.wait()
    try:
        if not out_tty: out=p.stdout.read()
        err=p.stderr.read()
    except: pass
    print(f'{label} args={args} in_tty={in_tty} out_tty={out_tty} -> {st}')
    print('  STDOUT:',repr(out[:250]))
    print('  STDERR:',repr(err[:250]))
    for m in masters:
        try: os.close(m)
        except: pass

tty_run([], 1, 1, wait=1.5, label='no-arg tty in + tty out')
tty_run([], 1, 0, wait=1.5, label='no-arg tty in + pipe out')
